import sqlite3
import os
import re
import json
import logging


def get_alarms_from_excel(excel_path, filtered_severity_levels, filtered_alarm_ids=None,
                          fault_id_column='Fault ID and name', filter_empty_alarm_ids=False, ignore_faults=None):
    from pandas import read_excel
    alarms_excel = read_excel(open(excel_path, 'rb'))
    alarms_excel.fillna('', inplace=True)
    alarms = {}
    row = 1
    for fault_id_and_name, alarms_description in zip(alarms_excel[fault_id_column],
                                                     alarms_excel['Reported alarms description']):
        row += 1
        alarm_ids_with_severity = _get_alarm_ids_with_severity_from_description(
            alarms_description,
            filtered_alarm_ids=filtered_alarm_ids,
            filtered_severity_levels=filtered_severity_levels,
            ignore_faults=ignore_faults
        )
        if filter_empty_alarm_ids and not alarm_ids_with_severity:
            continue
        else:
            fault_ids = re.findall(r'\d+:', fault_id_and_name)
            alarm_ids_json = json.dumps(alarm_ids_with_severity)
            for fault_id in fault_ids:
                if ignore_faults and int(fault_id[:-1]) in ignore_faults:
                    continue
                alarms[fault_id[:-1]] = alarm_ids_json
    return alarms


def _get_alarm_ids_with_severity_from_description(alarms_description, filtered_severity_levels,
                                                  filtered_alarm_ids=None, ignore_faults=None):
    lines = alarms_description.split('\n')
    current_alarm_id = None
    alarm_ids_with_severity = {}
    for line in lines:
        # Check if the line contains 4 digit number that is the only one digit in line, which indicates a new key
        match = re.match(r'\b(\d{4})\b', line)
        if match:
            try:
                if not alarm_ids_with_severity[current_alarm_id]:
                    alarm_ids_with_severity.pop(current_alarm_id)
            except KeyError:
                pass
            current_alarm_id = str(match.group(1))
            if filtered_alarm_ids:
                if current_alarm_id not in filtered_alarm_ids:
                    current_alarm_id = None
            if current_alarm_id:
                alarm_ids_with_severity[current_alarm_id] = []

        elif current_alarm_id:
            # Check if the line contains any of the severity levels
            for severity in filtered_severity_levels:
                if line.startswith(f"{severity}:"):
                    # Only take the part before the colon if it exists
                    severity_label = line.split(':')[0].strip()
                    alarm_ids_with_severity[current_alarm_id].append(severity_label.capitalize())
                    break

    return alarm_ids_with_severity


def _setup_logger():
    logger = logging.getLogger('db_creation')
    logger.setLevel(logging.DEBUG)
    console_handler = logging.StreamHandler()
    console_handler.setLevel(logging.INFO)

    formatter = logging.Formatter('\033[34m%(levelname)s - %(message)s\033[0m')
    console_handler.setFormatter(formatter)

    logger.addHandler(console_handler)

    return logger


if __name__ == '__main__':
    excel_path = 'some/path/to/excel.xlsx'
    logger = _setup_logger()

    logger.info("Installing pandas and openpyxl...")
    os.system('pip install pandas openpyxl > /dev/null')
    logger.info("Libraries installed successfully!")

    logger.info("Fetching all existing alarms from excel file")
    allowed_alarms = get_alarms_from_excel(
        excel_path=excel_path,
        filtered_severity_levels=["Warning", "Critical", "Minor", "Major", "warning", "critical", "minor", "major"]
    )

    logger.info("Updating `alarms` table in the database...")
    db = sqlite3.connect('alarms.db')
    cursor = db.cursor()

    for fault_id, alarm_ids in allowed_alarms.items():
        print(f"Inserting fault ID {fault_id} with alarms {alarm_ids}")
        cursor.execute("""
        INSERT INTO alarms (fault_id, alarm_ids)
        VALUES (?, ?)
        ON CONFLICT(fault_id) DO UPDATE SET alarm_ids=excluded.alarm_ids
        """, (fault_id, alarm_ids))

    db.commit()
    db.close()
    logger.info("Table `alarms` updated!")
